def transform_candidate(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg_values = set(counts) - {bg}
    out = [row[:] for row in grid]
    if len(fg_values) != 1:
        return out
    fg = next(iter(fg_values))
    active = [any(v == fg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        end = r
        while end + 1 < h and active[end + 1]:
            end += 1
        bands.append((r, end))
        r = end + 1
    if len(bands) < 2:
        return out
    b0, b1 = bands[0], bands[-1]
    right0 = max(c for rr in range(b0[0], b0[1] + 1) for c, v in enumerate(grid[rr]) if v == fg)
    right1 = max(c for rr in range(b1[0], b1[1] + 1) for c, v in enumerate(grid[rr]) if v == fg)
    if right0 == right1:
        return out
    source, target = (b0, b1) if right0 > right1 else (b1, b0)
    count = source[1] - source[0] + 1
    if count != target[1] - target[0] + 1:
        return out
    for k in range(count):
        a = grid[source[0] + k]
        b = grid[target[0] + k]
        last = max((c for c, v in enumerate(b) if v == fg), default=-1)
        options = []
        for d in range(-6, 7):
            expected = set()
            matches = missing = extra = 0
            for c, v in enumerate(a):
                q = c + d
                if 0 <= q < w and v == fg:
                    expected.add(q)
                    if b[q] == fg:
                        matches += 1
                    else:
                        missing += 1
            extra = sum(v == fg and c not in expected for c, v in enumerate(b))
            score = matches - 0.5 * (missing + extra) - 0.75 * abs(d)
            options.append((score, -abs(d), -d, expected))
        expected = max(options)[3]
        for c in expected:
            if c > last and b[c] == bg:
                out[target[0] + k][c] = 1
    # If a solid continuation is repeated on adjacent lines, keep its whole run marked.
    marked_runs = []
    for rr in range(h):
        runs=[]; c=0
        while c<w:
            if out[rr][c] != 1:
                c+=1; continue
            e=c
            while e+1<w and out[rr][e+1]==1: e+=1
            if e-c+1>=5: runs.append((c,e))
            c=e+1
        marked_runs.append(runs)
    for rr in range(h):
        for s,e in marked_runs[rr]:
            for neighbor in (rr-1,rr+1):
                if 0<=neighbor<h and any(ns==s and ne>=e for ns,ne in marked_runs[neighbor]):
                    # extend through the same uninterrupted input color
                    color=grid[rr][s]
                    q=e+1
                    while q<w and grid[rr][q]==color:
                        out[rr][q]=1; q+=1
    return out

